  "test": "import pytest
from types import SimpleNamespace

from langfuse._client.span_filter import is_app_root_eligible


def test_is_app_root_eligible_ineligible_span():
    """Spans with scope 'openai' and name 'ChatCompletion' should not be app roots."""
    # parent present to trigger eligibility check
    parent = SimpleNamespace()
    span = SimpleNamespace(
        parent=parent,
        instrumentation_scope=SimpleNamespace(name="openai"),
        name="ChatCompletion",
    )
    assert is_app_root_eligible(span) is False
